/**
 * emit to subscription queries of type FindPerformanceReview,
 * but only if the id matches
 *
 * @param		entity	PerformanceReview
 */
	protected void emitFindPerformanceReview( PerformanceReview entity ) {
		LOGGER.info("handling emitFindPerformanceReview" );
		
	    queryUpdateEmitter.emit(FindPerformanceReviewQuery.class,
	                            query -> query.getFilter().getPerformanceReviewId().equals(entity.getPerformanceReviewId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPerformanceReview
	 * 
	 * @param		entity	PerformanceReview
	 */
	protected void emitFindAllPerformanceReview( PerformanceReview entity ) {
		LOGGER.info("handling emitFindAllPerformanceReview" );
		
	    queryUpdateEmitter.emit(FindAllPerformanceReviewQuery.class,
	                            query -> true,
	                            entity);
	}

